(() => {
  const fpsInput = document.getElementById('ftc-fps-input');
  const msInput = document.getElementById('ftc-ms-input');
  const rawInput = document.getElementById('ftc-raw-input');
  const calcBtn = document.getElementById('ftc-calc-btn');
  const sampleBtn = document.getElementById('ftc-load-sample-btn');
  const resAvgFps = document.getElementById('res-avg-fps');
  const res1PctLow = document.getElementById('res-1pct-low');
  const resPoint1PctLow = document.getElementById('res-point1pct-low');
  const resMeanMs = document.getElementById('res-mean-ms');
  const resStdDevMs = document.getElementById('res-stddev-ms');
  const resStutterCount = document.getElementById('res-stutter-count');
  const graphCanvas = document.getElementById('ftc-graph-canvas');
  const graphCtx = graphCanvas?.getContext('2d');

  // Bidirectional conversion
  fpsInput.addEventListener('input', () => {
    const fps = parseFloat(fpsInput.value) || 0;
    if (fps > 0) {
      msInput.value = (1000 / fps).toFixed(2);
    }
  });

  msInput.addEventListener('input', () => {
    const ms = parseFloat(msInput.value) || 0;
    if (ms > 0) {
      fpsInput.value = (1000 / ms).toFixed(1);
    }
  });

  document.querySelectorAll('#ftc-budget-presets button').forEach((btn) => {
    btn.addEventListener('click', () => {
      const fps = parseFloat(btn.dataset.fps);
      fpsInput.value = fps;
      msInput.value = (1000 / fps).toFixed(2);
    });
  });

  function drawGraph(times, mean) {
    if (!graphCtx || times.length === 0) return;
    const w = graphCanvas.width;
    const h = graphCanvas.height;
    graphCtx.clearRect(0, 0, w, h);

    const maxTime = Math.max(40, ...times) * 1.15;
    const count = times.length;

    // Draw target 16.67ms line
    const y60 = h - (16.67 / maxTime) * h;
    graphCtx.strokeStyle = '#e2e8f0';
    graphCtx.setLineDash([4, 4]);
    graphCtx.beginPath();
    graphCtx.moveTo(0, y60);
    graphCtx.lineTo(w, y60);
    graphCtx.stroke();
    graphCtx.setLineDash([]);

    // Plot frame time line
    graphCtx.strokeStyle = '#4f46e5';
    graphCtx.lineWidth = 1.5;
    graphCtx.beginPath();
    times.forEach((t, i) => {
      const x = (i / (count - 1 || 1)) * w;
      const y = h - (t / maxTime) * h;
      if (i === 0) graphCtx.moveTo(x, y);
      else graphCtx.lineTo(x, y);
    });
    graphCtx.stroke();
  }

  function analyze() {
    const text = rawInput.value.trim();
    if (!text) return;

    const isFpsMode = document.querySelector('input[name="ftc-input-mode"]:checked')?.value === 'fps';
    const tokens = text.split(/[\s,;\n\r]+/);
    const values = [];

    tokens.forEach((t) => {
      const n = parseFloat(t.trim());
      if (isFinite(n) && n > 0) {
        values.push(isFpsMode ? 1000 / n : n);
      }
    });

    if (values.length === 0) return;

    const sorted = [...values].sort((a, b) => a - b);
    const count = sorted.length;
    const sum = sorted.reduce((a, b) => a + b, 0);
    const mean = sum / count;
    const avgFps = mean > 0 ? 1000 / mean : 0;

    const idx99 = Math.min(count - 1, Math.floor(count * 0.99));
    const p99 = sorted[idx99];
    const onePctLow = p99 > 0 ? 1000 / p99 : 0;

    const idx999 = Math.min(count - 1, Math.floor(count * 0.999));
    const p999 = sorted[idx999];
    const pointOnePctLow = p999 > 0 ? 1000 / p999 : 0;

    const variance = sorted.reduce((acc, v) => acc + Math.pow(v - mean, 2), 0) / count;
    const stdDev = Math.sqrt(variance);
    const stutters = sorted.filter((v) => v >= mean * 1.5).length;

    resAvgFps.textContent = avgFps.toFixed(1);
    res1PctLow.textContent = onePctLow.toFixed(1);
    resPoint1PctLow.textContent = pointOnePctLow.toFixed(1);
    resMeanMs.textContent = mean.toFixed(2) + ' ms';
    resStdDevMs.textContent = stdDev.toFixed(2) + ' ms';
    resStutterCount.textContent = stutters + ' frames';

    drawGraph(values, mean);
  }

  sampleBtn.addEventListener('click', () => {
    // Generate 120 realistic 60fps frames with 3 stutter spikes
    const sample = [];
    for (let i = 0; i < 120; i++) {
      if (i === 35) sample.push(33.4);
      else if (i === 72) sample.push(42.1);
      else if (i === 105) sample.push(29.8);
      else sample.push((16.4 + Math.random() * 0.6).toFixed(1));
    }
    rawInput.value = sample.join(', ');
    analyze();
  });

  calcBtn.addEventListener('click', analyze);
  sampleBtn.click();
})();
